import{_ as r,C as s,c as n,o as i,a3 as t,G as a}from"./chunks/framework.Dokpd4od.js";const g=JSON.parse('{"title":"Two step flow","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/inventories/routes/two-step-flow.md","filePath":"master/supply-chain/inventories/routes/two-step-flow.md","lastUpdated":1792041590000}'),d={name:"master/supply-chain/inventories/routes/two-step-flow.md"};function l(h,e,c,p,u,m){const o=s("ImagePopup");return i(),n("div",null,[e[0]||(e[0]=t('<h1 id="two-step-flow" tabindex="-1">Two step flow <a class="header-anchor" href="#two-step-flow" aria-label="Permalink to &quot;Two step flow&quot;">​</a></h1><p>The two step flow adds one staging step. Received goods wait in <code>WH/Input</code> until someone stores them. Outgoing goods are picked from stock into <code>WH/Output</code> before the final delivery. Each step is its own document.</p><blockquote><p><strong>In simple words:</strong> Receive, then store. Or pick, then deliver.</p></blockquote><h2 id="when-to-use-it" tabindex="-1">When to use it <a class="header-anchor" href="#when-to-use-it" aria-label="Permalink to &quot;When to use it&quot;">​</a></h2><ul><li>Goods arrive in bulk and are put away later.</li><li>You want to prepare orders before the truck comes.</li><li>Different people receive and store.</li></ul><h2 id="set-it-in-the-warehouse" tabindex="-1">Set it in the warehouse <a class="header-anchor" href="#set-it-in-the-warehouse" aria-label="Permalink to &quot;Set it in the warehouse&quot;">​</a></h2><ol><li>Open <code>Inventory → Configurations → Warehouse Management → Warehouses</code>.</li><li>Click <strong>Edit</strong> on your warehouse.</li><li>Set <strong>Incoming Shipments</strong> to <strong>Receive then Store (Two steps)</strong>.</li><li>Set <strong>Outgoing Shipments</strong> to <strong>Pick then Deliver (Two steps)</strong>.</li><li>Click <strong>Save changes</strong>.</li></ol>',7)),a(o,{src:"/images1/inventory/route_wh_two_step.png",alt:"Warehouse edit form with the radio changed on screen but not yet saved: Incoming Shipments Receive then Store (Two steps) and Outgoing Shipments Pick then Deliver (Two steps)"}),e[1]||(e[1]=t('<div class="info custom-block"><p class="custom-block-title">INFO</p><p>Needs <code>Inventory → Settings → Manage Warehouses → Multi Steps Routes</code> and <code>Locations</code> on.</p></div><h2 id="documents-created" tabindex="-1">Documents created <a class="header-anchor" href="#documents-created" aria-label="Permalink to &quot;Documents created&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Flow</th><th>Document</th><th>Prefix</th><th>Path</th></tr></thead><tbody><tr><td>Receipt</td><td>Receipts</td><td>WH/IN</td><td>Partners/Vendors → WH/Input</td></tr><tr><td>Receipt</td><td>Storage</td><td>WH/STOR</td><td>WH/Input → WH/Stock</td></tr><tr><td>Delivery</td><td>Pick</td><td>WH/PICK</td><td>WH/Stock → WH/Output</td></tr><tr><td>Delivery</td><td>Delivery Orders</td><td>WH/OUT</td><td>WH/Output → Partners/Customers</td></tr></tbody></table><p>The second document appears when you validate the first. The prefixes are the ones used in the example warehouse.</p><h2 id="example-receiving" tabindex="-1">Example: receiving <a class="header-anchor" href="#example-receiving" aria-label="Permalink to &quot;Example: receiving&quot;">​</a></h2><p>You receive 15 SSD 512GB from Consolidated Components.</p><ol><li>Open receipt WH/IN/11 and click <strong>Validate</strong>. The SSDs land in <code>WH/Input</code>.</li><li>A storage transfer WH/STOR/n is created and shows <strong>Ready</strong>.</li><li>Open it from <code>Inventory → Operations → Transfers → Internal Transfers</code>.</li><li>Click <strong>Validate</strong>. The SSDs move to <code>WH/Stock</code>.</li></ol><p>The screenshot shows a finished storage transfer, WH/STOR/37, from the three-step example warehouse. It moves goods from <code>WH/Quality Control</code> to <code>WH/Stock</code>. In the two-step flow the same kind of document moves goods from <code>WH/Input</code> to <code>WH/Stock</code>.</p>',8)),a(o,{src:"/images1/inventory/route_two_step_storage.png",alt:"Storage transfer WH/STOR/37 in Done state moving Laptop Chassis and LCD Screen 14-inch from WH/Quality Control to WH/Stock, taken from the three-step example warehouse"}),e[2]||(e[2]=t('<p>On a finished receipt, the <strong>Next Transfer</strong> button jumps to the follow-up document.</p><h2 id="example-delivering" tabindex="-1">Example: delivering <a class="header-anchor" href="#example-delivering" aria-label="Permalink to &quot;Example: delivering&quot;">​</a></h2><p>Confirming a sales order creates the delivery WH/OUT and a pick WH/PICK. Validate the pick first. Goods move to <code>WH/Output</code>. Then validate WH/OUT so they reach the customer.</p><h2 id="what-you-do-at-each-step" tabindex="-1">What you do at each step <a class="header-anchor" href="#what-you-do-at-each-step" aria-label="Permalink to &quot;What you do at each step&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Step</th><th>Your action</th></tr></thead><tbody><tr><td>Receive</td><td>Validate WH/IN</td></tr><tr><td>Store</td><td>Validate WH/STOR</td></tr><tr><td>Pick</td><td>Validate WH/PICK</td></tr><tr><td>Deliver</td><td>Validate WH/OUT</td></tr></tbody></table><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./">Routes overview</a></li><li><a href="./one-step-flow.html">One step flow</a></li><li><a href="./three-step-flow.html">Three step flow</a></li><li><a href="./../operations/internal-transfers.html">Internal transfers</a></li><li><a href="./putaway-rules.html">Putaway rules</a></li></ul>',7))])}const w=r(d,[["render",l]]);export{g as __pageData,w as default};
